83:   reserveInitiative,
84:   type InitiativeDraft,
85: } from "./initiative/generator.js";
86: import {
87:   getInitiativeStatus,
88: } from "./initiative/cooldown.js";
89: import {
90:   isProactivePausedDb,
91:   releaseInitiativeLease,
92:   setProactivePausedDb,
93:   tryAcquireInitiativeLease,
94: } from "./initiative/lease.js";
95: import { noteUserSleepState } from "./initiative/sleep.js";
96: import type { ChatChannel } from "./memory/types.js";
97: 
98: export type DiscordPresence = {
99:   status: "online" | "idle";
100:   label: string;
101: };
102: 
103: export type ChatRequest = {
104:   message: string;
105:   channel: ChatChannel;
106:   ownerId: string;
107:   threadId?: string;
108:   auditSessionId?: string | null;
109:   imageUrls?: string[];
110:   /** Discord bot's last applied custom status; omitted on telegram/voice. */
111:   discordPresence?: DiscordPresence;
112: };
113: 
114: const NUDGE_KINDS = new Set<CandidateKind>([
115:   "she_owes",
116:   "he_never_answered",
117: ]);
118: 
119: export type ChatStreamEvent =
120:   | { type: "delta"; text: string }
121:   | {
122:       type: "done";
123:       text: string;
124:       model: string;
125:       threadId: string;
126:     }
127:   | { type: "error"; code: string; message: string };
128: 
129: export class ChatService {
130:   private readonly db: DatabaseSync;
131:   private readonly assembler: MemoryAssembler;
132:   readonly consolidator: ConsolidationWorker;
133:   private activeOwner: string | null = null;
134:   private abortController: AbortController | null = null;
135: 
136:   constructor(db?: DatabaseSync) {
137:     this.db = getMemoryDb(db);
138:     this.assembler = new MemoryAssembler(this.db);
139:     this.consolidator = new ConsolidationWorker(this.db);
140:     this.consolidator.start();
141:   }
142: 
143:   isBusy(ownerId: string): boolean {
144:     return this.activeOwner === ownerId;
145:   }
146: 
147:   cancel(): void {
148:     this.abortController?.abort();
149:     this.abortController = null;
150:     this.activeOwner = null;
151:     setTurnBusy(false);
152:   }
153: 
154:   /**
155:    * The bot asks this before the turn so it can say "hang on, looking" while the
156:    * search / page read and the generation are still running. Pure predicates
157:    * plus budget counts, no network.
158:    */
159:   lookupPreflight(message: string): boolean {
160:     const queryMode = classifyQuery(message);
161:     if (linkReadPreflight(message, queryMode)) return true;
162:     const decision = extractImmediateHttpsUrl(message);
163:     const stripUrl =
164:       decision.kind === "immediate" || decision.kind === "mention"
165:         ? decision.url
166:         : null;
167:     return this.lookupAllowed(message, queryMode, stripUrl);
168:   }
169: 
170:   private lookupAllowed(
171:     message: string,
172:     queryMode: string,
173:     stripUrl: string | null = null,
174:   ): boolean {
175:     if (!env.curiosityLookupEnabled || !env.tavilyApiKey) return false;
176:     if (queryMode !== "normal") return false;
177:     if (!shouldLookupAsideUrl(message, stripUrl)) return false;
178:     return canSpendTavily(this.db);
179:   }
180: 
181:   /**
182:    * A search credit is only spent when he asked her to look or the question is
183:    * about something current. Recall turns never search: those are about him.
184:    * A supplied URL is stripped so we never spend a credit searching the link.
185:    */
186:   private async maybeLookUp(
187:     message: string,
188:     queryMode: string,
189:     stripUrl: string | null = null,
190:   ): Promise<string | null> {
191:     if (!this.lookupAllowed(message, queryMode, stripUrl)) return null;
192:     const query = shouldLookupAsideUrl(message, stripUrl);
193:     if (!query) return null;
194:     const hits = await searchWeb(this.db, query);
195:     return buildSearchContext(query, hits);
196:   }
197: 
198:   async *stream(request: ChatRequest): AsyncGenerator<ChatStreamEvent> {
199:     if (!env.mistralApiKey) {
200:       yield {
201:         type: "error",
202:         code: "agent_not_ready",
203:         message: "Mistral API key not configured",
204:       };
205:       return;
206:     }
207: 
208:     if (this.activeOwner === request.ownerId) {
209:       yield {
210:         type: "error",
211:         code: "chat_in_progress",
212:         message: "Chat already in progress",
213:       };
214:       return;
215:     }
216: 
217:     this.activeOwner = request.ownerId;
218:     this.abortController = new AbortController();
219:     setTurnBusy(true);
220: 
221:     try {
222:       const threadId =
223:         request.threadId ??
224:         resolveActiveThread(this.db, request.ownerId, request.channel);
225: 
226:       const herLast = lastAssistantText(this.db, request.ownerId);
227: 
228:       const userMsgId = insertMessage(this.db, {
229:         threadId,
230:         ownerId: request.ownerId,
231:         role: "user",
232:         text: request.message,
233:         channel: request.channel,
234:         tokenEstimate: estimateTokens(request.message),
235:         auditSessionId: request.auditSessionId,
236:       });
237: 
238:       // Anything he comes back to stops being unfinished; what he anchors to a
239:       // time, or leaves hanging, becomes material for a follow-up later.
240:       noteUserSleepState(this.db, request.ownerId, request.message);
241:       closeThreadsTouchedBy(this.db, request.ownerId, request.message);
242:       closeMismatchedOpenThreads(this.db, request.ownerId, request.message);
243:       noteUnansweredQuestion(this.db, request.ownerId, herLast, request.message);
244:       noteOpenThreads(this.db, request.ownerId, {
245:         role: "user",
246:         text: request.message,
247:         messageId: userMsgId,
248:       });
249: 
250:       handleForgetRequest(this.db, request.ownerId, request.message);
251:       syncDenylistFromThread(this.db, request.ownerId, threadId);
252: 
253:       applyAutoRemember(
254:         this.db,
255:         request.ownerId,
256:         threadId,
257:         userMsgId,
258:         request.message,
259:         this.consolidator,
260:       );
261: 
262:       this.consolidator.afterMessage(
263:         request.ownerId,
264:         threadId,
265:         userMsgId,
266:         "user",
267:       );
268: 
269:       const assembled = await this.assembler.build(
270:         request.ownerId,
271:         request.channel,
272:         request.message,
273:         threadId,
274:         userMsgId,
275:       );
276: 
277:       const promptParts = loadSystemPrompt(request.channel);
278: 
279:       const askKind = activityAskKind(request.message);
280:       const activityAsk = askKind !== null;
281:       const curiosityMode = activityAsk ? "solicited" : "organic";
282:       // Voice skips unsolicited reading texture (TTS budget). Direct asks still
283:       // get a license so she cannot invent under hasReadActivity.
284:       const curiosity =
285:         request.channel === "voice" && curiosityMode === "organic"
286:           ? null
287:           : assembleCuriosity(this.db, request.message, {
288:               mode: curiosityMode,
289:               askKind: askKind ?? undefined,
290:             });
291: 
292:       const capabilityNote =
293:         request.channel !== "voice" && isBrowsePermission(request.message)
294:           ? buildCapabilityBlock(env.curiosityEnabled)
295:           : null;
296: 
297:       // Text only for v1: voice latency / TTS budget stays unchanged.
298:       const linkDecision = extractImmediateHttpsUrl(request.message);
299: 
300:       // Sharp: decide once before voice select; regen must reuse this arm.
301:       const sharpBlocked =
302:         activityAsk ||
303:         linkDecision.kind === "immediate" ||
304:         isBrowsePermission(request.message);
305:       const sharpDecision = decideSharpMode({
306:         channel: request.channel,
307:         queryMode: assembled.queryMode,
308:         message: request.message,
309:         lastAt: readSharpLastAt(this.db, request.ownerId),
310:         blocked: sharpBlocked,
311:       });
312:       const sharpArmed = sharpDecision.armed;
313:       const sharpNote = sharpArmed ? sharpLicenseNote() : null;
314: 
315:       const examples =
316:         env.personaFewshotEnabled && assembled.queryMode !== "recall"
317:           ? selectVoiceExamples({
318:               message: request.message,
319:               seed: assembled.threadId,
320:               max: env.personaFewshotCount,
321:               allowSharp: sharpArmed,
322:               extraTags:
323:                 assembled.queryMode === "soft_recall"
324:                   ? ["fabrication_bait", "recall_empty"]
325:                   : [],
326:             })
327:           : [];
328:       const linkUrl =
329:         linkDecision.kind === "immediate" || linkDecision.kind === "mention"
330:           ? linkDecision.url
331:           : null;
332:       const linkResult =
333:         request.channel === "voice"
334:           ? { pageContext: null as string | null, guard: null as string | null, success: false }
335:           : await maybeReadLink(this.db, request.message, assembled.queryMode);
336:       const pageContext = linkResult.pageContext;
337:       const linkFailed = Boolean(linkResult.guard) && !linkResult.success;
338: 
339:       const searchContext = await this.maybeLookUp(
340:         request.message,
341:         assembled.queryMode,
342:         linkDecision.kind === "immediate" ? linkUrl : null,
343:       );
344: 
345:       // Wanted a lookup, did not get one: she has to say so instead of guessing.
346:       // Activity asks are not lookups; skip the offline-lookup guard for them.
347:       const wantedLookup = Boolean(
348:         shouldLookupAsideUrl(
349:           request.message,
350:           linkDecision.kind === "immediate" ? linkUrl : null,
351:         ),
352:       );
353:       const lookupGuard =
354:         !activityAsk && !searchContext && wantedLookup ? NO_LOOKUP_GUARD : null;
355:       const linkGuard = linkResult.guard;
356:       const capabilityChallengeGuard =
357:         env.curiosityEnabled && isBrowseCapabilityChallenge(request.message)
358:           ? CAPABILITY_GUARD.text
359:           : null;
360:       const guardParts = [
361:         isPremiseCheck(request.message) ? PREMISE_GUARD : null,
362:         capabilityChallengeGuard,
363:         lookupGuard,
364:         linkGuard,
365:       ].filter(Boolean);
366:       const guard = guardParts.length > 0 ? guardParts.join("\n\n") : null;
367: 
368:       const presenceNote =
369:         request.channel === "discord"
370:           ? buildDiscordPresenceNote(request.discordPresence)
371:           : null;
372: 
373:       const buildMessages = (
374:         withExamples: VoiceExample[],
375:         withCuriosity: CuriosityInjection = curiosity,
376:       ) =>
377:         buildChatMessages({
378:           system: appendMemoryBlock(promptParts, assembled.memoryBlock, {
379:             presence: presenceNote,
380:             capability: capabilityNote,
381:             curiosity: withCuriosity?.text,
382:             sharp: sharpNote,
383:             voice: buildVoiceBlock(withExamples),
384:             guard,
385:           }),
386:           hot: assembled.hotMessages,
387:           message: request.message,
388:           imageUrls: request.imageUrls,
389:           searchContext,
390:           pageContext,
391:         });
392: 
393:       const messages = buildMessages(examples);
394: 
395:       let full = "";
396:       const temp =
397:         assembled.queryMode === "recall"
398:           ? env.mistralRecallTemperature
399:           : request.channel === "voice"
400:             ? env.mistralVoiceTemperature
401:             : env.mistralChatTemperature;
402:       // soft_recall stays on the conversational budget: it is a question about a
403:       // past exchange, not a memory audit, and clamping it to 120 is what makes
404:       // her sound like she is reading off an index card.
405:       const maxTokens =
406:         assembled.queryMode === "recall"
407:           ? 120
408:           : request.channel === "voice"
409:             ? 512
410:             : 2048;
411: 
412:       // Text chat only: recall wants stable phrasing and voice is short enough
413:       // that penalising repeats mostly costs coherence.
414:       const presencePenalty =
415:         assembled.queryMode !== "recall" && request.channel !== "voice"
416:           ? env.mistralChatPresencePenalty
417:           : undefined;
418: 
419:       // Banter stays fast; recall and soft_recall get the extra thinking budget.
420:       const reasoningEffort =
421:         assembled.queryMode === "normal" && request.message.trim().length < 80
422:           ? ("none" as const)
423:           : assembled.queryMode === "recall" ||
424:               assembled.queryMode === "soft_recall" ||
425:               request.message.trim().length > 160
426:             ? ("high" as const)
427:             : ("none" as const);
428: 
429:       const sampling = {
430:         maxTokens,
431:         temperature: temp,
432:         presencePenalty,
433:         reasoningEffort,
434:         signal: this.abortController.signal,
435:         lane: "interactive" as const,
436:       };
437: 
438:       // Text channels hold the deltas back so a copied sample or a fabricated
439:       // "I read" can be regenerated before Doc sees it. Voice keeps streaming,
440:       // because there the latency is audible.
441:       const buffered = request.channel !== "voice";
442: 
443:       for await (const delta of streamChat(messages, sampling)) {
444:         full += delta;
445:         if (!buffered) yield { type: "delta", text: delta };
446:       }
447: 
448:       // At most one regeneration per turn — stacked rewrites become compliance prose.
449:       if (buffered && full) {
450:         const recentAssistant = assembled.hotMessages
451:           .filter((m) => m.role === "assistant")
452:           .map((m) => m.content)
453:           .slice(-6);
454: 
455:         type Regen = { reason: string; messages: ReturnType<typeof buildMessages> };
456:         let regen: Regen | null = null;
457: 
458:         if (examples.length > 0 && looksLikeParrot(full, examples)) {
459:           regen = { reason: "parrot", messages: buildMessages([]) };
460:         } else if (isEchoOfUser(full, request.message)) {
461:           regen = {
462:             reason: "echo",
463:             messages: buildMessages(examples, {
464:               text: NO_ECHO_GUARD,
465:               takeIds: [],
466:               provenance: "mention",
467:             }),
468:           };
469:         } else if (
470:           isPremiseCheck(request.message) &&
471:           acceptedUncheckedPremise(full)
472:         ) {
473:           regen = {
474:             reason: "premise",
475:             messages: buildMessages(examples, {
476:               text: PREMISE_GUARD,
477:               takeIds: [],
478:               provenance: "mention",
479:             }),
480:           };
481:         } else if (env.curiosityEnabled && deniesOwnCapability(full)) {
482:           regen = {
483:             reason: "capability",
484:             messages: buildMessages(
485:               examples,
486:               linkFailed ? LINK_FAILED_CAPABILITY_GUARD : CAPABILITY_GUARD,
487:             ),
488:           };
489:         } else if (
490:           claimsOwnActivity(full) &&
491:           !searchContext &&
492:           !pageContext &&
493:           (linkFailed ||
494:             (!hasReadActivity(this.db, 24) &&
495:               !(curiosity && curiosity.takeIds.length > 0)))
496:         ) {
497:           // Empty solicited honesty still counts as no content license.
498:           // A failed link-read must not be masked by an unrelated idle read.
499:           regen = {
500:             reason: "activity",
501:             messages: buildMessages(examples, NO_ACTIVITY_GUARD),
502:           };
503:         } else if (looksLikeRepeat(full, recentAssistant)) {
504:           regen = {
505:             reason: "repeat",
506:             messages: buildMessages(examples, {
507:               text: NO_REPEAT_GUARD,
508:               takeIds: [],
509:               provenance: "mention",
510:             }),
511:           };
512:         }
513: 
514:         if (regen) {
515:           console.warn(`[chat] ${regen.reason}, regenerating once`);
516:           full = "";
517:           for await (const delta of streamChat(regen.messages, sampling)) {
518:             full += delta;
519:           }
520:           if (regen.reason === "capability") {
521:             const floored = applyCapabilityHardFloor(full);
522:             if (floored !== full) {
523:               console.warn("[chat] capability hard floor after regen");
524:               full = floored;
525:             }
526:           }
527:         }
528: 
529:         // After any regen rewrite: drop within-turn restating bubbles so Doc
530:         // never sees the double (and memory matches what he saw).
531:         if (full) {
532:           const collapsed = collapseWithinTurnRepeat(full);
533:           if (collapsed !== full) {
534:             console.warn("[chat] within-turn restatement collapsed");
535:             full = collapsed;
536:           }
537:         }
538:       }
539: 
540:       full = sanitizeTypography(full);
541: 
542:       if (buffered && full) {
543:         yield { type: "delta", text: full };
544:       }
545: 
546:       const persisted = stripMediaMarkers(full);
547:       // Marker-only / empty drafts must not land in hot history — Mistral 400s
548:       // on empty assistant content and every later turn glitches.
549:       if (!persisted.trim()) {
550:         console.warn("[chat] skipping empty assistant persist");
551:         yield {
552:           type: "done",
553:           text: full,
554:           model: env.mistralModel,
555:           threadId: assembled.threadId,
556:         };
557:         return;
558:       }
559: 
560:       // Only after a real reply persists does the surfacing count, so a
561:       // regenerated or empty turn does not burn the daily cap.
562:       if (curiosity) commitCuriosity(this.db, curiosity);
563: 
564:       const assistantId = insertMessage(this.db, {
565:         threadId,
566:         ownerId: request.ownerId,
567:         role: "assistant",
568:         text: persisted,
569:         channel: request.channel,
570:         tokenEstimate: estimateTokens(persisted),
571:         auditSessionId: request.auditSessionId,
572:       });
573: 
574:       if (sharpArmed && full) {
575:         commitSharpArmed(this.db, request.ownerId);
576:       }
577: 
578:       noteOpenThreads(this.db, request.ownerId, {
579:         role: "assistant",
580:         text: persisted,
581:         messageId: assistantId,
582:       });
583: 
584:       const mood = detectMoodFromText(persisted);
585:       if (mood) {
586:         recordMood(this.db, request.ownerId, mood, {
587:           sourceMessageId: assistantId,
588:         });
589:       }
590: 
591:       this.consolidator.afterMessage(
592:         request.ownerId,
593:         threadId,
594:         assistantId,
595:         "assistant",
596:       );
597: 
598:       yield {
599:         type: "done",
600:         text: full,
601:         model: env.mistralModel,
602:         threadId: assembled.threadId,
603:       };
604:     } catch (err) {
605:       if (err instanceof AppError) {
606:         yield { type: "error", code: err.code, message: err.message };
607:       } else if (err instanceof Error && err.name === "AbortError") {
608:         yield { type: "error", code: "internal_error", message: "Cancelled" };
609:       } else {
610:         yield {
611:           type: "error",
612:           code: "internal_error",
613:           message: err instanceof Error ? err.message : String(err),
614:         };
615:       }
616:     } finally {
617:       this.activeOwner = null;
618:       this.abortController = null;
619:       setTurnBusy(false);
620:     }
621:   }
622: 
623:   async complete(request: ChatRequest): Promise<{
624:     text: string;
625:     threadId: string;
626:     model: string;
627:   }> {
628:     let text = "";
629:     let threadId = request.threadId ?? "";
630:     let model = env.mistralModel;
631: 
632:     for await (const event of this.stream(request)) {
633:       if (event.type === "delta") text += event.text;
634:       if (event.type === "done") {
635:         text = event.text;
636:         model = event.model;
637:         threadId = event.threadId;
638:       }
639:       if (event.type === "error") {
640:         throw new AppError(
641:           event.code as AppError["code"],
642:           event.message,
643:           event.code === "chat_in_progress" ? 409 : 503,
644:         );
645:       }
646:     }
647: 
648:     const tid =
649:       threadId ||
650:       resolveActiveThread(this.db, request.ownerId, request.channel);
651:     return { text, threadId: tid, model };
652:   }
653: 
654:   pinMemory(
655:     ownerId: string,
656:     text: string,
657:     sensitivity: "none" | "private" = "none",
