667:     const threadId = resolveActiveThread(this.db, ownerId, "discord");
668:     return {
669:       facts: listActiveFacts(this.db, ownerId, 40, includePrivate),
670:       narrative: getActiveSummary(this.db, threadId),
671:       lastUpdated: new Date().toISOString(),
672:     };
673:   }
