681:   }
682: 
683:   getDebugContext(
684:     ownerId: string,
685:     userMessage?: string,
686:     channel: ChatChannel = "discord",
687:   ) {
688:     return this.assembler.getDebugContext(ownerId, userMessage, channel);
689:   }
690: 
691:   getMemoryHealth() {
692:     return getMemoryHealth(this.db);
693:   }
694: 
695:   recordReaction(ownerId: string, input: { messageId: string; emoji: string }) {
696:     return recordReaction(this.db, ownerId, input);
697:   }
698: 
699:   /** For the curiosity loop, which owns its own tables in the same file. */
700:   get database(): DatabaseSync {
701:     return this.db;
702:   }
703: 
704:   getDb() {
705:     return this.db;
706:   }
707: 
708:   getAssembler() {
709:     return this.assembler;
710:   }
711: 
712:   async evaluateInitiative(ownerId: string): Promise<EvaluateResult> {
713:     if (isProactivePausedDb(this.db, ownerId)) {
714:       return {
715:         shouldReachOut: false,
716:         reason: "proactive_paused",
717:         cooldownRemainingSec: 0,
718:       };
719:     }
720:     const cold = evaluateInitiative(this.db, ownerId, {
721:       busy: this.isBusy(ownerId),
722:       enabled: env.proactiveEnabled,
723:     });
724:     if (cold.shouldReachOut || cold.reason !== "user_active_recently") {
725:       return cold;
726:     }
727:     // He is around and she dropped something inside this session. That is a
728:     // nudge, not cold outreach, and it costs the same daily budget.
729:     if (!this.nudgeReady(ownerId)) return cold;
730:     const nudge = evaluateInitiative(this.db, ownerId, {
731:       busy: this.isBusy(ownerId),
732:       enabled: env.proactiveEnabled,
733:       nudge: true,
734:     });
735:     return nudge.candidate && NUDGE_KINDS.has(nudge.candidate.kind)
736:       ? nudge
737:       : cold;
738:   }
739: 
740:   /** Her own last word has to be stale, or a nudge is just interrupting. */
741:   private nudgeReady(ownerId: string): boolean {
742:     const row = this.db
743:       .prepare(
744:         `SELECT ts FROM mem_messages
745:          WHERE owner_id = ? AND role = 'assistant'
746:          ORDER BY id DESC LIMIT 1`,
747:       )
748:       .get(ownerId) as { ts: string } | undefined;
749:     if (!row) return false;
750:     const ageMin =
751:       (Date.now() - new Date(row.ts).getTime()) / 60_000;
752:     return ageMin >= env.proactiveNudgeIdleMinutes;
753:   }
