293: export function migrate(db: DatabaseSync): void {
294:   let version = (
295:     db.prepare("PRAGMA user_version").get() as { user_version: number }
296:   ).user_version;
297:   if (version < 1) {
298:     db.exec(SCHEMA_V1);
299:     db.exec("PRAGMA user_version = 1");
300:     version = 1;
301:   }
302:   if (version < 2) {
303:     db.exec(SCHEMA_V2);
304:     db.exec("PRAGMA user_version = 2");
305:     version = 2;
306:   }
307:   if (version < 3) {
308:     db.exec(SCHEMA_V3);
309:     db.exec("PRAGMA user_version = 3");
310:     version = 3;
