316:     if (!cols.some((c) => c.name === "facts_cutoff_message_id")) {
317:       db.exec(
318:         `ALTER TABLE mem_threads ADD COLUMN facts_cutoff_message_id INTEGER`,
319:       );
320:     }
321:     db.exec("PRAGMA user_version = 4");
322:     version = 4;
