329:     if (!tableNames.has("mem_initiative_log")) {
330:       db.exec(SCHEMA_V2);
331:     }
332:     const initCols = db
333:       .prepare(`PRAGMA table_info(mem_initiative_log)`)
334:       .all() as Array<{ name: string }>;
335:     if (!initCols.some((c) => c.name === "external_message_id")) {
336:       db.exec(
337:         `ALTER TABLE mem_initiative_log ADD COLUMN external_message_id TEXT`,
338:       );
339:       db.exec(
340:         `UPDATE mem_initiative_log
341:          SET external_message_id = discord_message_id
342:          WHERE external_message_id IS NULL
343:            AND discord_message_id IS NOT NULL`,
344:       );
345:     }
346:     db.exec(`
347: CREATE TABLE IF NOT EXISTS mem_reminders (
