369:   prompt_text     TEXT NOT NULL,
370:   enabled         INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
371:   last_fired_at   TEXT,
372:   streak_count    INTEGER NOT NULL DEFAULT 0,
373:   created_at      TEXT NOT NULL
374: );
375: CREATE INDEX IF NOT EXISTS idx_mem_habits_owner
376:   ON mem_habits (owner_id, enabled);
377: 
378: CREATE TABLE IF NOT EXISTS mem_habit_events (
379:   id             INTEGER PRIMARY KEY AUTOINCREMENT,
