447:     version = 8;
448:   }
449:   if (version < 9) {
450:     db.exec(`
451: CREATE TABLE IF NOT EXISTS mem_mood (
452:   id                INTEGER PRIMARY KEY AUTOINCREMENT,
453:   owner_id          TEXT NOT NULL,
454:   mood              TEXT NOT NULL,
