478:   SELECT id, kind, item_id, detail, created_at FROM cur_provenance;
479: DROP TABLE cur_provenance;
480: ALTER TABLE cur_provenance_v10 RENAME TO cur_provenance;
481: CREATE INDEX IF NOT EXISTS idx_cur_provenance_kind
482:   ON cur_provenance (kind, created_at);
483: `);
484:     db.exec("PRAGMA user_version = 10");
