495: const JOBS_PENDING_ALERT = env.memoryJobsPendingAlert;
496: 
497: export function incrementMemoryMetric(
498:   db: DatabaseSync,
499:   key: string,
500:   delta = 1,
501: ): void {
502:   const fullKey = `memory_metric:${key}`;
503:   const row = db
504:     .prepare(`SELECT value FROM mem_kv WHERE key = ?`)
505:     .get(fullKey) as { value: string } | undefined;
506:   const current = row ? Number(row.value) || 0 : 0;
507:   const now = new Date().toISOString();
508:   db.prepare(
509:     `INSERT INTO mem_kv (key, value, updated_at) VALUES (?, ?, ?)
510:      ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
511:   ).run(fullKey, String(current + delta), now);
512: }
