514: export function getMemoryMetrics(
515:   db: DatabaseSync,
516: ): Record<string, number> {
517:   const rows = db
518:     .prepare(`SELECT key, value FROM mem_kv WHERE key LIKE 'memory_metric:%'`)
519:     .all() as Array<{ key: string; value: string }>;
520:   const out: Record<string, number> = {};
521:   for (const r of rows) {
522:     out[r.key.replace("memory_metric:", "")] = Number(r.value) || 0;
523:   }
524:   return out;
525: }
