527: export function pruneOldDoneJobs(db: DatabaseSync, days = 7): number {
528:   const result = db
529:     .prepare(
530:       `DELETE FROM mem_jobs
531:        WHERE status = 'done'
532:          AND updated_at < datetime('now', ?)`,
533:     )
534:     .run(`-${days} days`);
535:   return Number(result.changes);
