538: export function getMemoryHealth(db: DatabaseSync): {
539:   ok: boolean;
540:   jobsPending: number;
541:   jobsPendingByType: Record<string, number>;
542:   jobsRunning: number;
543:   jobsStuck: number;
544:   jobsFailed: number;
545:   jobsDone: number;
546:   lastJobError: string | null;
547:   metrics: Record<string, number>;
548:   pendingAlertThreshold: number;
549: } {
550:   try {
551:     db.prepare("SELECT 1").get();
552:     const pending = db
553:       .prepare(
554:         `SELECT COUNT(*) AS c FROM mem_jobs WHERE status = 'pending'`,
555:       )
556:       .get() as { c: number };
557:     const pendingByType = db
558:       .prepare(
559:         `SELECT job_type, COUNT(*) AS c FROM mem_jobs
560:          WHERE status = 'pending' GROUP BY job_type`,
561:       )
562:       .all() as Array<{ job_type: string; c: number }>;
563:     const jobsPendingByType: Record<string, number> = {};
564:     for (const row of pendingByType) {
565:       jobsPendingByType[row.job_type] = row.c;
566:     }
567:     const running = db
568:       .prepare(`SELECT COUNT(*) AS c FROM mem_jobs WHERE status = 'running'`)
569:       .get() as { c: number };
570:     const stuck = db
571:       .prepare(
572:         `SELECT COUNT(*) AS c FROM mem_jobs
573:          WHERE status = 'running'
574:            AND lease_until IS NOT NULL
575:            AND lease_until < datetime('now')`,
576:       )
577:       .get() as { c: number };
578:     const failed = db
579:       .prepare(`SELECT COUNT(*) AS c FROM mem_jobs WHERE status = 'failed'`)
580:       .get() as { c: number };
581:     const done = db
582:       .prepare(`SELECT COUNT(*) AS c FROM mem_jobs WHERE status = 'done'`)
583:       .get() as { c: number };
584:     const lastErr = db
585:       .prepare(
586:         `SELECT last_error FROM mem_jobs
587:          WHERE last_error IS NOT NULL
588:          ORDER BY updated_at DESC LIMIT 1`,
589:       )
590:       .get() as { last_error: string } | undefined;
591:     const healthy =
592:       stuck.c === 0 &&
593:       failed.c === 0 &&
594:       pending.c <= JOBS_PENDING_ALERT;
595:     return {
596:       ok: healthy,
597:       jobsPending: pending.c,
598:       jobsPendingByType,
599:       jobsRunning: running.c,
600:       jobsStuck: stuck.c,
601:       jobsFailed: failed.c,
602:       jobsDone: done.c,
603:       lastJobError: lastErr?.last_error ?? null,
604:       metrics: getMemoryMetrics(db),
605:       pendingAlertThreshold: JOBS_PENDING_ALERT,
606:     };
607:   } catch {
608:     return {
609:       ok: false,
610:       jobsPending: 0,
611:       jobsPendingByType: {},
612:       jobsRunning: 0,
613:       jobsStuck: 0,
614:       jobsFailed: 0,
615:       jobsDone: 0,
616:       lastJobError: null,
617:       metrics: {},
618:       pendingAlertThreshold: JOBS_PENDING_ALERT,
619:     };
620:   }
621: }
